import json,numpy as np
from pathlib import Path
w=Path('work/character-finish32');z=np.load(w/'twist-motion-targets.npz');names=z['names'].tolist();F=z['features'];D=z['deltas'];report=json.loads((w/'twist-motion-profile-report.json').read_text());ids=[names.index(n) for n in report['selectedSamples']];src=json.loads((w/'twist-source/poses/male_intro.json').read_text());body=src['parts'][0];top=next(p for p in src['parts'] if p['name']=='Kit_Top');WI=np.array(top['indices']).reshape(-1,4);W=np.array(top['weights']).reshape(-1,4);rows=[]
for i,name in enumerate(names):
 distances=((F[ids]-F[i])**2).mean(1);nearest=np.argsort(distances)[:4];d=distances[nearest];weights=np.array([1.,0,0,0]) if d[0]<1e-10 else 1/np.maximum(d,1e-8)**2;weights/=weights.sum();approx=(D[np.array(ids)[nearest]]*weights[:,None,None]).sum(0);directory,label=name.split(':');matrix=json.loads((w/directory/'matrices'/f'{label}.json').read_text());bm=np.array(matrix['parts'][0]['skinMatrices']).reshape(-1,4,4);mp=dict(zip(body['bones'],bm));M=(np.array([mp[n] for n in top['bones']])[WI]*W[:,:,None,None]).sum(1);error=np.linalg.norm(np.einsum('nij,nj->ni',M[:,:3,:3],approx-D[i]),axis=1);rows.append({'sample':name,'maximumMm':float(error.max()*1000),'p95Mm':float(np.quantile(error,.95)*1000),'over2mm':int(sum(error>.002))})
rows.sort(key=lambda r:-r['maximumMm']);out={'samples':len(rows),'anchors':len(ids),'worst':rows[:20],'framesOver2mm':sum(r['maximumMm']>2 for r in rows),'maxMm':rows[0]['maximumMm']};(w/'twist-interpolation-report.json').write_text(json.dumps(out,indent=2));print(json.dumps(out),flush=True)
